const $=(s)=>document.querySelector(s);
const link=(t)=>`<a href="fichas/${t.id}.html">${t.name}</a>`;
function updateCards(){const q=($('#tech-search')?.value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const tag=$('#tech-filter').value;let count=0;document.querySelectorAll('.tech-card').forEach(el=>{const text=el.dataset.text.normalize('NFD').replace(/[\u0300-\u036f]/g,'');const visible=(!tag||el.dataset.tags.split(' ').includes(tag))&&(!q||text.includes(q));el.hidden=!visible;if(visible)count++});$('#tech-count').textContent=`${count} de ${items.length} tecnologias detalhadas`}
function updateScenario(){const s=scenarios.find(x=>x.id===$('#scenario-select').value)||scenarios[0];$('#scenario-detail').innerHTML=`<h3>${s.name}</h3><p><strong>Problema:</strong> ${s.goal}</p><p><strong>Por onde começar:</strong> ${s.tech.map(id=>link(items.find(x=>x.id===id))).join(' · ')}</p><p><strong>Justificativa:</strong> ${s.reason}</p><p><strong>Limite importante:</strong> ${s.caution}</p>`}
function updateComparison(){const a=items.find(x=>x.id===$('#compare-a').value),b=items.find(x=>x.id===$('#compare-b').value);$('#comparison').innerHTML=`<div class="comparison-grid">${[a,b].map(t=>`<article><h3>${link(t)}</h3><p><strong>Categoria:</strong> ${t.cat}</p><p><strong>O que faz:</strong> ${t.desc}</p><p><strong>Quando usar:</strong> ${t.when}</p><p><strong>Quando não é boa primeira escolha:</strong> ${t.avoid}</p><p><strong>Exemplo:</strong> ${t.example}</p></article>`).join('')}</div><p class="small-note"><strong>Como interpretar:</strong> compare papéis, necessidades e restrições; ferramentas de camadas diferentes podem ser combinadas em vez de escolhidas como alternativas.</p>`}
$('#tech-search').addEventListener('input',updateCards);$('#tech-filter').addEventListener('change',updateCards);$('#scenario-select').addEventListener('change',updateScenario);$('#compare-a').addEventListener('change',updateComparison);$('#compare-b').addEventListener('change',updateComparison);
$('#compare-a').value='openclaw';$('#compare-b').value='hermes-agent';updateCards();updateScenario();updateComparison();

