const catSelect=$('#full-cat');[...new Set(wholeCatalog.map(x=>x.cat))].sort().forEach(c=>{const opt=document.createElement('option');opt.value=c;opt.textContent=c;catSelect.appendChild(opt)});
function updateFullCatalog(){let q=$('#full-search').value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let cat=catSelect.value;const match=wholeCatalog.filter(x=>(!cat||x.cat===cat)&&((x.name+' '+x.cat+' '+x.description).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q)));$('#full-count').textContent=`${match.length} de ${wholeCatalog.length} fichas`;const box=$('#full-list');box.replaceChildren();for(const x of match){const el=document.createElement('div');el.className='catalog-index-item';const a=document.createElement('a');a.href=x.href;a.textContent=x.name;const label=document.createElement('small');label.textContent=x.cat;el.append(a,label);box.appendChild(el)}}
$('#full-search').addEventListener('input',updateFullCatalog);catSelect.addEventListener('change',updateFullCatalog);updateFullCatalog();
